#!/usr/bin/env bash
# Some portions generated by Codex. Run only after worker release and immutable-layer validation.
set -euo pipefail
cd "$(dirname "$0")/../../.."
: "${CP_A:?}" "${CP_AD:?}" "${CP_C0:?}" "${CP_C0D:?}" "${CP_C1:?}" "${CP_C1D:?}" "${LOCK:?}"
OUT=${OUT:-experiments/threadlocal-audit/read-depth/qualification-01}
[[ ! -e $OUT ]] || { echo "Refuse existing $OUT" >&2; exit 2; }
mkdir -p "$OUT/harness"
exec 9>"$LOCK"; flock 9
JAVA=../toolchain/jdk-25.0.5+8/bin/java; JAVAC=../toolchain/jdk-25.0.5+8/bin/javac
"$JAVAC" -cp "$CP_C1D" -d "$OUT/harness" experiments/threadlocal-audit/read-depth/ReadDepthQueryBenchmark.java
mapfile -t FLAGS < experiments/threadlocal-audit/best-flags.txt
run() {
 local arm=$1 regime=$2 adjacency=$3 groups=$4 warm=$5 label=$6 key=CP_$1 on=false
 [[ $arm == C1 || $arm == C1D ]] && on=true
 local -a cmd=("$JAVA" --enable-native-access=ALL-UNNAMED -Xms2g -Xmx3g "${FLAGS[@]}"
 -Drdf4j.lmdb.queryMemory.perQueryMaxBytes=671088640 -Drdf4j.lmdb.recordCancellation.trace=true
 "-Drdf4j.lmdb.recordCancellation.owned=$on" "-Daudit.regime=$regime" -Daudit.shape=narrow
 "-Daudit.adjacency=$adjacency" "-Doverlay.benchmark.warmups=$warm"
 -cp "$OUT/harness:${!key}" org.eclipse.rdf4j.sail.lmdb.evaluation.ReadDepthQueryBenchmark "$groups" 10 1 true)
 printf '%q ' "${cmd[@]}" > "$OUT/$label.command"
 "${cmd[@]}" > "$OUT/$label.log" 2>&1
}
for regime in regular interpreted janino; do
 for arm in A AD C0 C0D C1 C1D; do run "$arm" "$regime" true 2 0 "broad-$regime-$arm"; done
done
for arm in A AD C0 C0D C1 C1D; do run "$arm" janino false 2 0 "probes-janino-$arm"; done
for arm in C1 C1D; do run "$arm" janino false 100 20 "warm-probes-janino-$arm"; done
python3 experiments/threadlocal-audit/read-depth/summarize-qualification.py "$OUT" > "$OUT/summary.json"
